def _expand_hebbian(
    seeds: list[dict],
    max_hops: int = MAX_HOPS,
    branch: int = DEFAULT_BRANCH,
    decay: float = DECAY_PER_HOP,
) -> list[dict]:
    """BFS across hebbian edges with activation decay. Dedupes by node_id."""
    merged: dict[str, dict] = {s["node_id"]: dict(s) for s in seeds}
    frontier = [(s["node_id"], float(s["activation"]), 0) for s in seeds]

    for _hop in range(max_hops):
        next_frontier: list[tuple[str, float, int]] = []
        for nid, act, hop in frontier:
            if hop >= max_hops:
                continue
            try:
                neighbors = hebbian.top_edges(nid, k=branch)
            except Exception:
                neighbors = []
            for other_id, weight in neighbors:
                new_act = act * weight * decay
                if new_act < 0.02:
                    continue
                existing = merged.get(other_id)
                if existing is None:
                    merged[other_id] = {
                        "node_id": other_id,
                        "text": "",
                        "activation": round(new_act, 4),
                        "source": "system2_expand",
                        "hops": hop + 1,
                        "kind": "episodes",
                    }
                    next_frontier.append((other_id, new_act, hop + 1))
                elif new_act > existing["activation"]:
                    existing["activation"] = round(new_act, 4)
                    if hop + 1 < existing.get("hops", max_hops):
                        existing["hops"] = hop + 1
        frontier = next_frontier
        if not frontier:
            break

    return list(merged.values())


async def spreading_activate(
    query: str,
    datasets: list[str] | None = None,
    seed_k: int = DEFAULT_SEED_K,
    max_hops: int = MAX_HOPS,
    include_archived: bool = False,
    co_activation_strength: float = 0.1,
) -> list[dict]:
    """Full System 2 retrieval. Async because cognee.search is async."""
    seeds = await _seed_from_cognee(query, datasets, seed_k)
    if not seeds:
